import json
with open('/app/resources/treasury_bulletin_1939_04.json', 'r') as f:
    data = json.load(f)

# Search for Latin America related content
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'latin' in str(k).lower():
                print(f'Found key: {path}.{k}')
                print(f'Value: {v}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]')

search(data)
